<?php /* Template Name: Register */ if ( is_user_logged_in() ) { wp_safe_redirect( sd_auth_profile_url() ); exit; } get_header(); ?><main id="primary" class="sd-main sd-auth-main"><div class="sd-container sd-content-wrap"><div class="sd-auth-card"><div class="sd-auth-brand"><?php sd_render_site_branding(); ?></div><span class="sd-eyebrow"><?php esc_html_e( 'Join the community', 'social-discovery' ); ?></span><h1><?php esc_html_e( 'Create your account', 'social-discovery' ); ?></h1><p class="sd-auth-intro"><?php esc_html_e( 'Create a simple profile and start finding communities that fit.', 'social-discovery' ); ?></p><?php sd_auth_message(); ?><?php if ( get_option( 'users_can_register' ) ) : ?><?php if ( function_exists( 'sd_core_register_handler' ) ) : get_template_part( 'template-parts/auth/register-form' ); else : ?><p><?php esc_html_e( 'Registration is handled by WordPress.', 'social-discovery' ); ?></p><a class="sd-button sd-button-primary" href="<?php echo esc_url( wp_registration_url() ); ?>"><?php esc_html_e( 'Continue to registration', 'social-discovery' ); ?></a><?php endif; ?><?php else : ?><div class="sd-auth-message sd-auth-message-error" role="alert"><?php esc_html_e( 'Registration is currently disabled by the site administrator.', 'social-discovery' ); ?></div><?php endif; ?><p class="sd-auth-links"><a href="<?php echo esc_url( sd_auth_url( 'login', wp_login_url() ) ); ?>"><?php esc_html_e( 'Already have an account? Sign in', 'social-discovery' ); ?></a></p></div></div></main><?php get_footer(); ?>
